Exit fullscreen mode

You get runtime validation AND TypeScript types from the same definition.

Using in API Routes

// app/api/users/route.ts
import { NextRequest } from 'next/server';
import { z } from 'zod';
const CreateUserSchema = z.object({
name: z.string().min(2, 'Name must be at least 2 characters'),
email: z.string().email('Please enter a valid email'),
password: z.string()
.min(8, 'Password must be at least 8 characters')
.regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
.regex(/[0-9]/, 'Password must contain at least one number'),
});
export async function POST(request: NextRequest) {
const body = await request.json();
// safeParse never throws — returns result object
const result = CreateUserSchema.safeParse(body);
if (!result.success) {
return Response.json(
{
error: 'Validation failed',
// First error message — clean for users
message: result.error.errors[0].message,
// All errors — useful for forms
errors: result.error.flatten().fieldErrors,
},
{ status: 400 }
);
}
// result.data is fully typed here
const { name, email, password } = result.data;
// Save to database...
return Response.json({ success: true });
}

