Exit fullscreen mode

The z.coerce.number() is key — URL params are always strings, coerce converts them to numbers automatically.

Validating Environment Variables

// lib/env.ts
import { z } from 'zod';
const EnvSchema = z.object({
MONGODB_URI: z.string().url('Invalid MongoDB URI'),
JWT_SECRET: z.string().min(32, 'JWT secret must be at least 32 characters'),
NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
PORT: z.coerce.number().default(3000),
});
// Validate at startup — crashes immediately if env vars are missing
const result = EnvSchema.safeParse(process.env);
if (!result.success) {
console.error('Invalid environment variables:');
console.error(result.error.flatten().fieldErrors);
process.exit(1); // crash immediately with helpful error
}
export const env = result.data;

